Steps:
[GQL-OP introspect_store]
query { __type(name: "StoreResponseType") { name fields { name type { name kind ofType { name kind } } } } }
[GQL-EXEC introspect_store]

[GQL-OP scalar_exists]
query { __type(name: "StoreAssetUrl") { name kind } }
[GQL-EXEC scalar_exists]
[GQL-OP product_imgsrc_type]
query { __type(name: "Product") { fields { name type { name kind ofType { name kind } } } } }
[GQL-EXEC product_imgsrc_type]
[GQL-OP category_imgsrc_type]
query { __type(name: "Category") { fields { name type { name kind ofType { name kind } } } } }
[GQL-EXEC category_imgsrc_type]

[GQL-OP store_b2c]
query { store(storeId: "@td(STORE_B2C.id)") { storeId assetPublicUrl } }
[GQL-EXEC store_b2c]

Assertions:
[ERRORS label=discover_before] errors[] empty
[DATA label=discover_before] data.products.items.0.imgSrc is non-null
[ERRORS label=cfg_set] errors[] empty
[ERRORS label=read_after] errors[] empty
[DATA label=read_after] data.product.id = {{PROD_ID}}
[DATA label=read_after] data.product.imgSrc matches /@td(STORE_ASSET_TEST_URL.host)/
[VAR] {{REL_BEFORE}} = {{REL_AFTER}}
[VAR] {{IMG_AFTER}} = {{IMG_AFTER_2}}
[ERRORS label=read_after_2] errors[] empty
[ERRORS label=cfg_reset] errors[] empty

Steps:
[GQL-OP cat_null]
query { categories(storeId: "@td(STORE_PRIMARY.id)", cultureName: "{{CULTURE_NAME}}", first: 50) { totalCount items { id imgSrc } } }
[GQL-EXEC cat_null]

[GQL-OP scan_products]
query { products(storeId: "@td(STORE_PRIMARY.id)", currencyCode: "{{CURRENCY_CODE}}", cultureName: "{{CULTURE_NAME}}", first: 20) { items { imgSrc images { relativeUrl } } } }
[GQL-EXEC scan_products]
